CREATE TABLE [sales].[POSCounters]([CounterId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_POSCounters_Id] DEFAULT NEWSEQUENTIALID(),[CounterCode] NVARCHAR(30) NOT NULL,[CounterName] NVARCHAR(100) NOT NULL,[WarehouseId] UNIQUEIDENTIFIER NOT NULL,[InvoiceSeriesId] UNIQUEIDENTIFIER NOT NULL,[IsActive] BIT NOT NULL CONSTRAINT [DF_POSCounters_Active] DEFAULT 1,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_POSCounters_Created] DEFAULT SYSUTCDATETIME(),[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_POSCounters] PRIMARY KEY([CounterId]),CONSTRAINT [UQ_POSCounters_Code] UNIQUE([CounterCode]),CONSTRAINT [FK_POSCounters_Warehouse] FOREIGN KEY([WarehouseId]) REFERENCES [inventory].[Warehouses]([WarehouseId]),CONSTRAINT [FK_POSCounters_Series] FOREIGN KEY([InvoiceSeriesId]) REFERENCES [sales].[InvoiceSeries]([InvoiceSeriesId]));
